import{_ as t,o,c as a,a2 as r}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Meter reset and overflow","description":"","frontmatter":{"order":2,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/05.hintergrund/02.zaehler-reset.md"},"headers":[],"relativePath":"adapter/sourceanalytix/hintergrund/zaehler-reset.md","filePath":"adapter/sourceanalytix/hintergrund/zaehler-reset.md","lastUpdated":null}'),s={name:"adapter/sourceanalytix/hintergrund/zaehler-reset.md"};function n(i,e,d,h,l,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="meter-reset-and-overflow" tabindex="-1">Meter reset and overflow <a class="header-anchor" href="#meter-reset-and-overflow" aria-label="Permalink to &quot;Meter reset and overflow&quot;">​</a></h1><p><a id="device-reset-detected-mean-reset"></a></p><h2 id="what-does-device-reset-detected-mean-and-how-does-reset-detection-work" tabindex="-1">What does &quot;Device reset detected&quot; mean and how does reset detection work? <a class="header-anchor" href="#what-does-device-reset-detected-mean-and-how-does-reset-detection-work" aria-label="Permalink to &quot;What does &quot;Device reset detected&quot; mean and how does reset detection work?&quot;">​</a></h2><p><strong>In short:</strong> &quot;Device reset detected&quot; is a warning, not an error. SourceAnalytix noticed that the meter reading of your source dropped sharply (restart, power failure, overflow or meter swap), and from now on it keeps counting on top of the previous total. No consumption is lost and no negative values appear.</p><h3 id="the-terms" tabindex="-1">The terms <a class="header-anchor" href="#the-terms" aria-label="Permalink to &quot;The terms&quot;">​</a></h3><p>These terms apply throughout the documentation.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Target unit</td><td>The unit of the price definition you assigned to the source, e.g. kWh. SourceAnalytix calculates everything in it: total, start values and threshold.</td></tr><tr><td>Device value</td><td>The value of your source datapoint, converted to the target unit. It can fall back, e.g. after the device restarts.</td></tr><tr><td>Total</td><td>SourceAnalytix&#39;s own meter reading in the state <code>sourceanalytix.0.&lt;device&gt;.cumulativeReading</code>. With reset detection on, it never drops by itself.</td></tr><tr><td>Offset</td><td>The value <code>valueAtDeviceReset</code> in the SourceAnalytix settings of the source. The rule is: total = device value + offset. Without a reset it is 0. Up to v0.6.x no dialog shows it. From v0.7.0 it is on the source under &quot;For experts&quot;.</td></tr><tr><td>Start value</td><td>The total at the beginning of a period (&quot;Day&quot;, &quot;Week&quot;, &quot;Month&quot;, &quot;Quarter&quot;, &quot;Year&quot;). Consumption of the period = total − start value.</td></tr><tr><td>Threshold</td><td>The field &quot;Threshold&quot; in the settings of the source. The largest drop that still counts as measurement noise. In the target unit, default 1.</td></tr><tr><td>Reset</td><td>The device value falls by more than the threshold. The cause can be a restart, an overflow or a new meter.</td></tr></tbody></table><h3 id="how-detection-works" tabindex="-1">How detection works <a class="header-anchor" href="#how-detection-works" aria-label="Permalink to &quot;How detection works&quot;">​</a></h3><p>With every new device value, SourceAnalytix calculates device value + offset and compares the result with the last total:</p><ol><li><strong>Equal or higher:</strong> The value is accepted.</li><li><strong>Lower, but by no more than the threshold:</strong> This counts as measurement noise. The total stays where it is and the value is ignored.</li><li><strong>Lower by more than the threshold:</strong> This is a possible reset. SourceAnalytix keeps the total, writes &quot;Waiting for another reading before confirming a possible device reset&quot; to the log and waits for the next value.</li><li><strong>The next value decides:</strong><ul><li>If it is close to the old value again (within the threshold) or has climbed back more than halfway, the low value was an outlier. It is discarded, and the log says &quot;Rejected a possible device reset&quot;.</li><li>If it is equal to or higher than the low value but still low, the reset is confirmed. SourceAnalytix sets the offset to old total − low device value and reports &quot;Device reset detected for … preserving cumulative value … with new offset …&quot;. From now on, the device value keeps counting on top of the old total.</li><li>If it is even lower, SourceAnalytix keeps waiting.</li></ul></li></ol><p>An example with a threshold of 1 kWh: The meter reads 1,000 kWh and restarts at 0 after a power failure.</p><table tabindex="0"><thead><tr><th>Device value</th><th>Offset</th><th>Total</th><th>Log</th></tr></thead><tbody><tr><td>1,000 kWh</td><td>0</td><td>1,000 kWh</td><td>–</td></tr><tr><td>0 kWh</td><td>0</td><td>1,000 kWh</td><td>&quot;Waiting for another reading …&quot;</td></tr><tr><td>0.4 kWh</td><td>1,000</td><td>1,000.4 kWh</td><td>&quot;Device reset detected …&quot;</td></tr><tr><td>1.0 kWh</td><td>1,000</td><td>1,001 kWh</td><td>–</td></tr></tbody></table><p>The only thing lost is what the device counted between its last value before the reset and its first value after it, because the device itself no longer reported that part.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If the first value after a real reset has already climbed back more than halfway, SourceAnalytix takes it for an outlier. The consumption since the reset is then not counted, and the log says so with &quot;Rejected a possible device reset … If the device was really reset, consumption since the reset was not counted&quot;. You can correct this as described in <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correct wrong values</a>.</p></div><h3 id="overflow-power-failure-and-restart-of-sourceanalytix" tabindex="-1">Overflow, power failure and restart of SourceAnalytix <a class="header-anchor" href="#overflow-power-failure-and-restart-of-sourceanalytix" aria-label="Permalink to &quot;Overflow, power failure and restart of SourceAnalytix&quot;">​</a></h3><ul><li><strong>Overflow:</strong> A meter that starts again at 0 after reaching its maximum is an ordinary reset for SourceAnalytix.</li><li><strong>Power failure at the device:</strong> If the device starts at 0 or a lower value, that is also a reset.</li><li><strong>SourceAnalytix was stopped:</strong> The total is stored in the state <code>cumulativeReading</code>. A reset that happened in that time is detected at the first value after the start, as long as device value + offset is then still lower than the stored total by more than the threshold.</li><li><strong>Power sources (W):</strong> They have no reset detection. They don&#39;t deliver a meter reading that SourceAnalytix could compare.</li></ul><h3 id="when-reset-detection-is-off" tabindex="-1">When reset detection is off <a class="header-anchor" href="#when-reset-detection-is-off" aria-label="Permalink to &quot;When reset detection is off&quot;">​</a></h3><p>Without the checkbox &quot;Device value reset detection Enabled&quot;, SourceAnalytix accepts every drop. Total and period values then drop with it, and consumption can go negative. This is meant only for sources that are allowed to drop on purpose. The log says &quot;Cumulative reading for … decreased while reset detection is disabled&quot; with every drop.</p><p><strong>Up to v0.6.1:</strong> This message is logged at info level and can flood the log for sources that drop. <strong>From v0.6.2</strong>, it appears only in the debug log (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1262" target="_blank" rel="noreferrer">#1262</a>).</p><p>The older message &quot;Device reset detected … feature disabled (or below threshold)&quot; exists only up to v0.4.x. Since v0.5.0 it has been replaced by the messages above. If you still see it, update SourceAnalytix.</p><h3 id="what-changes-from-v0-6-2" tabindex="-1">What changes from v0.6.2 <a class="header-anchor" href="#what-changes-from-v0-6-2" aria-label="Permalink to &quot;What changes from v0.6.2&quot;">​</a></h3><p><strong>From v0.6.2:</strong> A confirmed reset is rolled back if the old device value returns in one step. Example: A device reports 1,000, then 0 twice, then 1,000 again. Up to v0.6.1, the total doubled to 2,000 in this case. From v0.6.2, SourceAnalytix restores the old offset, the total stays at 1,000, and the log says &quot;Rolled back the device reset of …&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1258" target="_blank" rel="noreferrer">#1258</a>).</p><p><strong>From v0.6.2:</strong> If the offset is larger than the total (usually after a manual correction or a meter swap), the source keeps running. SourceAnalytix warns &quot;Known valueAtDeviceReset … is larger than the known cumulative value …&quot; and sets the offset to total − device value at the next value. Up to v0.6.1, the source stopped instead with the error &quot;Check settings for … Known valueAtDeviceReset … &gt; known cumulative value … cannot proceed&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1257" target="_blank" rel="noreferrer">#1257</a>).</p><p><strong>See also:</strong> <a href="./../referenz/einstellungen#threshold-disabling-reset-detection-work">Threshold and turning off reset detection</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">Meter starts at 0 after a power failure</a> · <a href="./../fehlerbehebung/log-meldungen#error-known-valueatdevicereset-known-cumulative">Error &quot;Known valueAtDeviceReset &gt; known cumulative value&quot;</a></p><p><a id="counter-reset-0-daily-happens"></a></p><h2 id="counter-that-is-reset-to-0-every-day-what-happens-internally" tabindex="-1">Counter that is reset to 0 every day: what happens internally? <a class="header-anchor" href="#counter-that-is-reset-to-0-every-day-what-happens-internally" aria-label="Permalink to &quot;Counter that is reset to 0 every day: what happens internally?&quot;">​</a></h2><p><strong>In short:</strong> With reset detection on, SourceAnalytix treats the nightly drop to 0 like any other reset: It waits for the next value, then sets the offset and keeps counting the total. Only a small remainder is missing each night. With reset detection off, SourceAnalytix accepts the drop, and the previous day&#39;s consumption is subtracted again the next day.</p><h3 id="what-happens-during-the-night" tabindex="-1">What happens during the night <a class="header-anchor" href="#what-happens-during-the-night" aria-label="Permalink to &quot;What happens during the night&quot;">​</a></h3><p>An example with a threshold of 0.1 kWh. The daily counter read 4.2 kWh in the evening, and the offset from earlier nights is 1,000 kWh.</p><table tabindex="0"><thead><tr><th>Time</th><th>Device value</th><th>Offset</th><th>Total</th><th>What happens</th></tr></thead><tbody><tr><td>23:58</td><td>4.2 kWh</td><td>1,000</td><td>1,004.2 kWh</td><td>–</td></tr><tr><td>0:00</td><td>–</td><td>1,000</td><td>1,004.2 kWh</td><td>Period rollover: &quot;Day&quot; start value becomes 1,004.2 kWh</td></tr><tr><td>0:01</td><td>0 kWh</td><td>1,000</td><td>1,004.2 kWh</td><td>Log &quot;Waiting for another reading …&quot;</td></tr><tr><td>0:10</td><td>0.05 kWh</td><td>1,004.2</td><td>1,004.25 kWh</td><td>Log &quot;Device reset detected …&quot;, today 0.05 kWh</td></tr></tbody></table><p>The period rollover at 0:00 system time does not depend on the device. It sets the start values to the total, and because the total does not drop, the new day starts cleanly at 0. It therefore doesn&#39;t matter whether the device drops back shortly before or shortly after midnight. Only what the device counted between its last value before the drop and the drop itself is missing.</p><h3 id="when-it-goes-wrong" tabindex="-1">When it goes wrong <a class="header-anchor" href="#when-it-goes-wrong" aria-label="Permalink to &quot;When it goes wrong&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>What happens</th><th>Result</th></tr></thead><tbody><tr><td>Reset detection off</td><td>The total drops by the device&#39;s daily value</td><td>Daily value negative, month and year lose the previous day&#39;s consumption</td></tr><tr><td>Threshold larger than the daily consumption, e.g. 1 kWh with 0.6 kWh the day before</td><td>The drop counts as measurement noise, new values are ignored until they exceed the old reading</td><td>The start of the new day is missing</td></tr></tbody></table><p>For the right setting, see <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">My meter restarts at 0 every day</a>.</p><p><strong>From v0.7.0:</strong> The &quot;Add source&quot; wizard marks datapoints whose ID or name looks like a daily value with &quot;daily counter&quot;. If you choose one anyway, it advises you to answer the question &quot;Does the value sometimes drop to 0?&quot; with &quot;Yes&quot;. That switches reset detection on. If it is off for a source that drops, the &quot;Problems&quot; tab reports &quot;Meter drops to 0, reset detection is off&quot;.</p><h3 id="better-a-meter-that-doesn-t-drop-back" tabindex="-1">Better: a meter that doesn&#39;t drop back <a class="header-anchor" href="#better-a-meter-that-doesn-t-drop-back" aria-label="Permalink to &quot;Better: a meter that doesn&#39;t drop back&quot;">​</a></h3><p>A daily counter works, but a total counter is more accurate. If there is none, you can use the device&#39;s power as the source, or write your own continuously rising datapoint with a script and evaluate that.</p><p><strong>See also:</strong> <a href="#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean and how does reset detection work?</a> · <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Which datapoint do I activate: meter (kWh) or power (W)?</a> · <a href="./../anleitungen/quellen-und-einheiten#use-script-datapoints-unreliable-sources">Script datapoints for unreliable sources</a></p>',38)])])}const f=t(s,[["render",n]]);export{p as __pageData,f as default};
